export function topicLabel(slug: string): string {
  return TOPICS.find((t) => t.slug === slug)?.label ?? slug.replace(/_/g, ' ');
}

// Narrow the taxonomy to a role. A picker that offers a VP of Sales a question
// about code review is worse than a shorter one.
export function topicsFor(
  ladder?: Ladder,
  level?: Seniority,
  fn?: RoleFunction,
): Topic[] {
  return TOPICS.filter(
    (t) =>
      (!t.ladders.length || !ladder || t.ladders.includes(ladder)) &&
      (!t.levels.length || !level || t.levels.includes(level)) &&
      (!t.functions.length || !fn || t.functions.includes(fn)),
  );
}

export function storyStateLabel(state: StoryState): string {
  return { draft: 'Draft', rehearsed: 'Rehearsed', battle_tested: 'Battle-tested' }[
    state
  ];
}

export function roleLabel(role: RoleInLoop): string {
  return {
    recruiter: 'Recruiter',
    hiring_manager: 'Hiring manager',
    peer: 'Peer',
    skip: 'Skip level',
    bar_raiser: 'Bar raiser',
    cross_functional: 'Cross-functional',
    unknown: 'Not known yet',
  }[role];
}
